import fitz
doc = fitz.open('eprint/figure-4.pdf')
page = doc[0]
draws = page.get_drawings()
blue_stroke = (0.09799999743700027, 0.28600001335144043, 0.6159999966621399)
for i,d in enumerate(draws):
    if d['color'] and abs(d['color'][0]-0.098)<0.01 and abs(d['color'][2]-0.616)<0.01:
        pts = []
        for item in d['items']:
            if item[0]=='l':
                pts += [item[1], item[2]]
            elif item[0]=='c':
                pts += [item[1], item[4]]
            elif item[0]=='re':
                pts += [item[1].tl, item[1].br]
        xs = [p.x for p in pts]; ys=[p.y for p in pts]
        print(i, d['width'], len(pts), 'x:', round(min(xs),1), round(max(xs),1), 'y:', round(min(ys),1), round(max(ys),1))
